import{_ as e,c as l,aU as a,a as n}from"./chunks/framework.DIXiA2XH.js";const f=JSON.parse('{"title":"AI相关","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/ai/index.md","filePath":"note/ai/ai/index.md","lastUpdated":1785559210000}'),r={name:"note/ai/ai/index.md"};function i(o,t,s,d,g,h){return n(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="ai相关" tabindex="-1">AI相关 <a class="header-anchor" href="#ai相关" aria-label="Permalink to &quot;AI相关&quot;">​</a></h1><p>《动手学深度学习》：<a href="https://zh.d2l.ai/" target="_blank" rel="noreferrer">https://zh.d2l.ai/</a></p><h2 id="各大ai云平台" tabindex="-1">各大AI云平台 <a class="header-anchor" href="#各大ai云平台" aria-label="Permalink to &quot;各大AI云平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">云平台</th><th style="text-align:left;">公司</th><th style="text-align:left;">地址</th></tr></thead><tbody><tr><td style="text-align:left;">阿里百炼</td><td style="text-align:left;">阿里巴巴</td><td style="text-align:left;"><a href="https://bailian.console.aliyun.com" target="_blank" rel="noreferrer">https://bailian.console.aliyun.com</a></td></tr><tr><td style="text-align:left;">腾讯T平台</td><td style="text-align:left;">腾讯</td><td style="text-align:left;"><a href="https://cloud.tencent.com/product/ti" target="_blank" rel="noreferrer">https://cloud.tencent.com/product/ti</a></td></tr><tr><td style="text-align:left;">干帆平台</td><td style="text-align:left;">百度</td><td style="text-align:left;"><a href="https://console.bce.baidu.com/qianfan/overview" target="_blank" rel="noreferrer">https://console.bce.baidu.com/qianfan/overview</a></td></tr><tr><td style="text-align:left;">SiliconCloud</td><td style="text-align:left;">硅基流动</td><td style="text-align:left;"><a href="https://siliconflow.cn/zh-cn/siliconcloud" target="_blank" rel="noreferrer">https://siliconflow.cn/zh-cn/siliconcloud</a></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">火山方舟-火山引擎</td><td style="text-align:left;">字节跳动</td><td style="text-align:left;"><a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">https://www.volcengine.com/product/ark</a></td></tr></tbody></table><h2 id="相关术语" tabindex="-1">相关术语 <a class="header-anchor" href="#相关术语" aria-label="Permalink to &quot;相关术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">技术</th><th style="text-align:left;">大致时间</th><th style="text-align:left;">提出者/推动者</th><th style="text-align:left;">核心要解决的问题</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LLM</strong></td><td style="text-align:left;">2017年起</td><td style="text-align:left;">Google (Transformer)</td><td style="text-align:left;">让机器具备强大的语言理解和生成能力，成为“能说会道”的大脑。</td></tr><tr><td style="text-align:left;"><strong>RAG</strong></td><td style="text-align:left;">2020年</td><td style="text-align:left;">Facebook AI Research</td><td style="text-align:left;">解决 LLM 知识过时、容易产生“幻觉”（胡说八道）的问题，为它配上“精准知识库”。</td></tr><tr><td style="text-align:left;"><strong>Agent</strong></td><td style="text-align:left;">2022年起</td><td style="text-align:left;">学术界与工业界共同演进</td><td style="text-align:left;">让 LLM 不仅能“说”，还能“做”。通过规划和使用工具，实现复杂任务的自动化。</td></tr><tr><td style="text-align:left;"><strong>MCP</strong></td><td style="text-align:left;">2024年底</td><td style="text-align:left;">Anthropic</td><td style="text-align:left;">解决 Agent 调用各种工具时接口混乱、开发成本高、安全性差的问题，统一工具的“插头标准”。</td></tr></tbody></table><p>一句话总结演进关系：</p><p>LLM 是基础大脑 → RAG 给它配上知识库，让它更聪明 → Agent 给它配上手脚，让它能干活 → MCP 统一了手脚的接口，让它干活更标准、更高效。</p><h3 id="🧠llm大语言模型-助手的-大脑" tabindex="-1">🧠LLM大语言模型：助手的“大脑” <a class="header-anchor" href="#🧠llm大语言模型-助手的-大脑" aria-label="Permalink to &quot;🧠LLM大语言模型：助手的“大脑”&quot;">​</a></h3><ul><li><p>通俗解释：LLM (Large Language Model) 是这个助手的“大脑”，负责思考、理解和生成语言。它能和你流畅对话，但它有一个“致命弱点”：它的知识只来源于训练时的数据，有个明确的截止日期，并且没有“记忆”。</p></li><li><p>举个例子：如果你问它“如何写一封商务邮件？”，它能立刻给你一份漂亮的模板。但如果你问“我们公司上个季度的销售额是多少？”，它就不知道了，因为它没学过你们公司的内部数据，甚至可能会“瞎编”一个数字（这就是 AI 的“幻觉”问题）。</p></li></ul><h3 id="📚-rag-检索增强生成-助手的-专属知识库" tabindex="-1">📚 RAG (检索增强生成)：助手的“专属知识库” <a class="header-anchor" href="#📚-rag-检索增强生成-助手的-专属知识库" aria-label="Permalink to &quot;📚 RAG (检索增强生成)：助手的“专属知识库”&quot;">​</a></h3><ul><li><p>通俗解释：RAG (Retrieval-Augmented Generation) 就是为了解决 LLM 的“失忆”和“幻觉”问题。它相当于给助手配备了一个可以随时查阅的“专属知识库”或“参考书”。当助手需要回答专业问题时，会先去知识库里查找资料，再结合资料给出精准答案。</p></li><li><p>举个例子：还是“上个季度销售额”的问题。有了 RAG，助手会先去连接着你公司内部数据库的“知识库”里检索相关信息，找到“上季度销售额为500万”这个确切数据，然后再告诉你。这样，回答就变得准确、可靠了。</p></li></ul><h3 id="🛠️-skills-技能-助手的-工具箱" tabindex="-1">🛠️ Skills (技能)：助手的“工具箱” <a class="header-anchor" href="#🛠️-skills-技能-助手的-工具箱" aria-label="Permalink to &quot;🛠️ Skills (技能)：助手的“工具箱”&quot;">​</a></h3><ul><li><p>通俗解释：Skills 是助手可以使用的各种“工具”或“能力”。LLM 这个“大脑”只能动嘴皮子（生成文本），但 Skills 能让它“动手做事”。</p></li><li><p>举个例子：每一个具体的工具都是一个 Skill，比如：</p><ul><li>查询数据库：一个能执行 SQL 语句的技能。</li><li>生成图表：一个能把数据变成柱状图或饼图的技能。</li><li>发送邮件：一个能调用邮件 API 的技能。</li></ul></li></ul><p>没有 Skills，助手就只能陪你聊天；有了 Skills，它才能真正帮你完成任务。</p><h3 id="📖-mcp-模型上下文协议-助手的-工作流程手册" tabindex="-1">📖 MCP (模型上下文协议)：助手的“工作流程手册” <a class="header-anchor" href="#📖-mcp-模型上下文协议-助手的-工作流程手册" aria-label="Permalink to &quot;📖 MCP (模型上下文协议)：助手的“工作流程手册”&quot;">​</a></h3><ul><li><p>通俗解释：MCP (Model Context Protocol) 是一本标准化的“工作流程手册”或“通用接口”。它规定了助手在接到任务后，应该按什么顺序、在什么情况下调用哪个技能，避免手忙脚乱。你可以把它想象成 AI 领域的 USB-C 接口，它统一了各种工具的连接标准，让助手能轻松“插上即用”，而无需为每个工具单独开发适配器。</p></li><li><p>举个例子：当你下达“分析数据并做图”的指令时，MCP 这本“手册”会告诉助手：“第一步，先调用‘查询数据库’技能获取数据；第二步，拿到数据后，再调用‘生成图表’技能。” 如果没有 MCP，助手可能会先尝试调用“生成图表”技能，结果因为没有数据而报错。</p></li></ul><h3 id="🎬-完整场景串联" tabindex="-1">🎬 完整场景串联 <a class="header-anchor" href="#🎬-完整场景串联" aria-label="Permalink to &quot;🎬 完整场景串联&quot;">​</a></h3><p>让我们回到最初的复杂任务，看看这五个概念是如何协同工作的：</p><p><strong>你的指令</strong>：“分析一下上个季度的销售数据，做个图表，然后发邮件给团队。”</p><ol><li><strong>Agent (助手本人)</strong> 接收到你的指令。</li><li><strong>LLM (大脑)</strong> 开始思考，理解这个任务需要分三步：查数据、做图表、发邮件。</li><li><strong>MCP (流程手册)</strong> 提供了标准流程：先查数据 → 再做图 → 最后发邮件。</li><li><strong>Agent</strong> 遵循流程，首先调用 <strong>Skills (工具箱)</strong> 里的 <code>查询数据库</code> 技能。</li><li>为了获取准确数据，这个技能会通过 <strong>RAG (知识库)</strong> 从公司内部数据库中检索到“上季度销售额为500万”。</li><li><strong>Agent</strong> 拿到数据后，接着调用 <code>生成图表</code> 技能，做出一个漂亮的柱状图。</li><li>最后，<strong>Agent</strong> 调用 <code>发送邮件</code> 技能，将图表和分析结果发送给团队。</li></ol><ul><li><strong>完整的技术流程：</strong><ol><li><strong>用户</strong> 给 <strong>Agent</strong> 指令。</li><li><strong>Agent</strong> 里的 <strong>LLM</strong> 进行思考（推理）。</li><li><strong>LLM</strong> 发现需要工具，于是发出一个符合 <strong>MCP 标准</strong> 的请求（比如：“我要调用 <code>query_db</code> 工具”）。</li><li><strong>Agent</strong>（作为 MCP 客户端）接收到请求，通过 <strong>MCP 协议</strong> 找到对应的 <strong>Skill</strong> 并执行。</li><li><strong>Skill</strong> 返回结果。</li><li><strong>Agent</strong> 把结果再次喂给 <strong>LLM</strong> 生成最终回复。</li></ol></li></ul>',22)])])}const p=e(r,[["render",i]]);export{f as __pageData,p as default};
